-- migrate:up
CREATE VIEW pub_api_tide WITH (security_barrier = true) AS
SELECT d.series_id, d.kind, d.ts, d.value, d.hilo
FROM tide d
JOIN series_eff e ON e.series_id = d.series_id
WHERE e.audience IN ('public') AND e.role = 'primary' AND e.lic_display AND e.lic_api
  AND (e.lic_history_export OR d.ts >= statement_timestamp() - e.history_window)
  AND EXISTS (SELECT 1 FROM public.station st WHERE st.id = e.station_id AND st.flags ->> 'tidal' = 'true');

CREATE VIEW own_api_tide WITH (security_barrier = true) AS
SELECT d.series_id, d.kind, d.ts, d.value, d.hilo
FROM tide d
JOIN series_eff e ON e.series_id = d.series_id
WHERE e.audience IN ('public', 'owner') AND e.role = 'primary' AND e.lic_display AND e.lic_api
  AND (e.lic_history_export OR d.ts >= statement_timestamp() - e.history_window)
  AND EXISTS (SELECT 1 FROM public.station st WHERE st.id = e.station_id AND st.flags ->> 'tidal' = 'true');

CREATE FUNCTION pub_tide_at(p_t timestamptz)
RETURNS TABLE (series_id int, kind text, hilo text, ts timestamptz, value real)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
SET TimeZone = 'UTC'
ROWS 1500
AS $$
  WITH tidal AS MATERIALIZED (
    SELECT e.series_id, e.lic_history_export, e.history_window, s.staleness_limit
    FROM public.series_eff e
    JOIN public.series s ON s.id = e.series_id
    WHERE s.active AND e.audience IN ('public') AND e.role = 'primary' AND e.lic_display
      AND EXISTS (SELECT 1 FROM public.station st WHERE st.id = e.station_id AND st.flags ->> 'tidal' = 'true')
  )
  SELECT e.series_id, d.kind, d.hilo, d.ts, d.value
  FROM tidal e
  JOIN public.tide d ON d.series_id = e.series_id
  WHERE d.kind = 'astro' AND d.ts <= p_t AND d.ts > p_t - e.staleness_limit
    AND (e.lic_history_export OR d.ts >= statement_timestamp() - e.history_window)
  UNION ALL
  SELECT e.series_id, d.kind, d.hilo, d.ts, d.value
  FROM tidal e
  CROSS JOIN (VALUES ('extreme_astro', 'high'), ('extreme_astro', 'low'), ('extreme', 'high'), ('extreme', 'low'))
    k (kind, hilo)
  CROSS JOIN LATERAL (
    SELECT d.kind, d.hilo, d.ts, d.value
    FROM public.tide d
    WHERE d.series_id = e.series_id AND d.kind = k.kind AND d.hilo = k.hilo
      AND d.ts <= p_t AND d.ts > p_t - interval '15 hours'
      AND (e.lic_history_export OR d.ts >= statement_timestamp() - e.history_window)
    ORDER BY d.ts DESC
    LIMIT 1) d
  UNION ALL
  SELECT e.series_id, d.kind, d.hilo, d.ts, d.value
  FROM tidal e
  CROSS JOIN (VALUES ('high'), ('low')) k (hilo)
  CROSS JOIN LATERAL (
    SELECT d.kind, d.hilo, d.ts, d.value
    FROM public.tide d
    WHERE d.series_id = e.series_id AND d.kind = 'extreme_astro' AND d.hilo = k.hilo
      AND d.ts > p_t AND d.ts <= p_t + interval '15 hours'
      AND (e.lic_history_export OR d.ts >= statement_timestamp() - e.history_window)
    ORDER BY d.ts
    LIMIT 1) d
$$;
REVOKE ALL ON FUNCTION pub_tide_at(timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pub_tide_at(timestamptz) TO rws_api, rws_publish;

